// TH15 v1.00b Stage 3 boss, 5th nonspell (st03bs.ecl.txt Boss3 442-503 + Boss3_at 505-595).
// Card frame 0 starts the segment timer; the source intro (setInvuln(120) + wait(60)x2)
// is the 120-frame opening buffer, then Boss3_at bursts alternate with moveRand(60,4,1.0).

const TIME_LIMIT: int = 2524;        // 120 opening + 2400 source window + 4 slack
const OPENING_BUFFER: int = 120;

// Source type 5 -> TH15_BALL2 (radius 4, colors 0-15), synthetic slot reuse per bullet-types.md.
const TH15_BALL2: int = 432;

// Source %E step 1.941611 rad, in BAM (65536 / 2*pi).
const E_STEP: int = 20252;
// Source %B = 0.017453292 rad = 1 deg per etAngle increment.
const B_STEP: int = 182;

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);        // source setHitbox(48,48): ordinary circle radius = 48/2
    set_hurtbox(20fx);       // source setHurtbox(40,40): radius = 40/2
    loop {
        // Boss3_1156: @Boss3_at(pi, -1deg); wait(20); moveRand; wait(60); @Boss3_at(0, +1deg); ...
        boss3_at(32768, -B_STEP);
        card_wait(20);
        move_rand();
        card_wait(60);
        boss3_at(0, B_STEP);
        card_wait(20);
        move_rand();
        card_wait(60);
    }
}

// Boss3_at: etNew/etAim(3)/etCount(2,1)/etSpeed(%C,0) then a 200-iteration fire loop.
// The configured etSpeed(1.5 for E/N/H, 2.1 for L) is overwritten by %C before every etOn.
sub boss3_at(a0: int, bstep: int) {
    var rank: int = global(GVAR_RANK);
    // floatTime(1, %C, 200, 0, start, goal); stack top is the first of the two refs.
    var s_start: fx = 1fx;
    var s_goal: fx = 3fx;
    if rank == 2 { s_start = 2fx; s_goal = 4fx; }
    if rank >= 3 { s_start = 2fx; s_goal = 5fx; }
    var fpi: int = 1;               // source !EN adds a second wait(1) per iteration
    if rank <= 1 { fpi = 2; }
    var f2: int = a0;
    var e: int = rand(65536);        // %RANDRAD: consumed only through cos/sin
    for k in 0..200 {
        var col: int = 6;
        if k >= 101 { col = 4; }     // source $D==100 -> etSprite(0/1, 5, 4)
        var t: int = k * fpi;
        if t > 200 { t = 200; }
        var sp: fx = s_start + (s_goal - s_start) * (t as fx) / 200fx;
        var ox: fx = 64fx * cos(e as angle);
        var oy: fx = 64fx * sin(e as angle);
        fire_ring(col, $self_x + ox, $self_y + oy, sp, f2);
        card_wait(1);                // source wait(1) between the two emitters
        f2 = f2 + bstep;
        if rank >= 1 {
            t = k * fpi + 1;
            if t > 200 { t = 200; }
            var sp2: fx = (s_start + (s_goal - s_start) * (t as fx) / 200fx) * 0.5fx;
            fire_ring(col, $self_x + ox, $self_y - oy, sp2, -f2);
        }
        f2 = f2 + bstep;
        e = e - E_STEP;
        if rank <= 1 { card_wait(1); }
    }
}

// etAim(3) fixed ring, count 2 / 1 layer: angles ang and ang+180deg.
// EX record 0 is ANIM a=1: birth position -= 4*velocity (layer record 0x2000000 omitted as render-only).
sub fire_ring(col: int, x: fx, y: fx, sp: fx, ang: int) {
    var c: fx = cos(ang as angle);
    var s: fx = sin(ang as angle);
    var back: fx = 4fx * sp;
    _ = fire(TH15_BALL2, col, x - back * c, y - back * s, sp, ang as angle, none, none);
    _ = fire(TH15_BALL2, col, x + back * c, y + back * s, sp, (ang + 32768) as angle, none, none);
}

// Enemy shared slots used by the moveRand recipe: int 0 = next-step count, fx 0/1 = unit direction.
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }   // moveLimit(0,128,280,96): x in [-140,140]
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }       // y in [80,176]
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub begin_move(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}

// moveRand(60, 4, 1.0): one signed random direction, speed 1 -> 0 over 60 steps.
// Direction inner region is the limit centre +/- half the limit size / 2 (x +/-70, y 104..152).
sub move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }   // source normalizes only this branch
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_move(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 18500, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
